CREATE TABLE IF NOT EXISTS renja_perubahan_submissions (id TEXT PRIMARY KEY, bureau_id TEXT, nama_biro TEXT NOT NULL, year INTEGER NOT NULL, stage TEXT DEFAULT 'rancangan_perubahan', status TEXT DEFAULT 'belum_upload', current_version INTEGER DEFAULT 0, score REAL, level_kesiapan TEXT, has_critical_open INTEGER DEFAULT 0, submitted_by TEXT, submitted_at TEXT, verifikator TEXT, approval_note TEXT, approved_by TEXT, approved_at TEXT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_rp_sub_biro ON renja_perubahan_submissions(nama_biro, year);
CREATE TABLE IF NOT EXISTS renja_perubahan_versions (id TEXT PRIMARY KEY, submission_id TEXT, version_number INTEGER NOT NULL, stage TEXT, main_file_url TEXT, main_file_name TEXT, lampiran_urls TEXT, checksum TEXT, extraction_status TEXT DEFAULT 'pending', extracted_content TEXT, nomor_registrasi TEXT, tanggal_dokumen TEXT, nama_penyusun TEXT, pejabat_penanggung_jawab TEXT, catatan TEXT, uploaded_by TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_rp_ver_sub ON renja_perubahan_versions(submission_id);
CREATE TABLE IF NOT EXISTS renja_perubahan_findings (id TEXT PRIMARY KEY, version_id TEXT, submission_id TEXT, nama_biro TEXT, year INTEGER, version_number INTEGER, category TEXT, severity TEXT DEFAULT 'minor', chapter TEXT, page TEXT, item_pemeriksaan TEXT, description TEXT, document_value TEXT, reference_value TEXT, reference_source TEXT, recommendation TEXT, status TEXT DEFAULT 'terbuka', verifier_note TEXT, operator_response TEXT, is_ai_generated INTEGER DEFAULT 0, finding_code TEXT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_rp_find_sub ON renja_perubahan_findings(submission_id);
CREATE INDEX IF NOT EXISTS idx_rp_find_ver ON renja_perubahan_findings(version_id);
CREATE TABLE IF NOT EXISTS renja_perubahan_references (id TEXT PRIMARY KEY, year INTEGER, document_type TEXT, title TEXT, nama_file TEXT, file_url TEXT, file_key TEXT, version TEXT DEFAULT '1', active INTEGER DEFAULT 1, priority INTEGER DEFAULT 4, keterangan TEXT, uploaded_by TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_rp_ref_year ON renja_perubahan_references(year);
CREATE TABLE IF NOT EXISTS renja_perubahan_setda (id TEXT PRIMARY KEY, year INTEGER NOT NULL, version INTEGER DEFAULT 1, status TEXT DEFAULT 'draft', ringkasan TEXT, generated_by TEXT, generated_at TEXT, approved_by TEXT, approved_at TEXT, approval_note TEXT, mode TEXT DEFAULT 'draft_konsolidasi', total_pagu_awal REAL DEFAULT 0, total_pagu_perubahan REAL DEFAULT 0, jumlah_biro_final INTEGER DEFAULT 0, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_rp_setda_year ON renja_perubahan_setda(year);
CREATE TABLE IF NOT EXISTS renja_perubahan_sections (id TEXT PRIMARY KEY, setda_id TEXT, chapter TEXT, subchapter TEXT, judul TEXT, content TEXT, status TEXT DEFAULT 'belum_disusun', urutan REAL, created_at TEXT DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_rp_sec_setda ON renja_perubahan_sections(setda_id);
CREATE TABLE IF NOT EXISTS renja_perubahan_sources (id TEXT PRIMARY KEY, setda_id TEXT, nama_biro TEXT, version_id TEXT, version_number INTEGER, source_location TEXT, source_type TEXT, data_value TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_rp_src_setda ON renja_perubahan_sources(setda_id);
CREATE TABLE IF NOT EXISTS renja_perubahan_notifications (id TEXT PRIMARY KEY, target_role TEXT, nama_biro TEXT, type TEXT, message TEXT, is_read INTEGER DEFAULT 0, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY, user_id TEXT, user_name TEXT, user_role TEXT, action TEXT, object_type TEXT, object_id TEXT, notes TEXT, metadata TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_audit_obj ON audit_log(object_type, object_id);
CREATE TABLE IF NOT EXISTS renja_perubahan_setda_findings (id TEXT PRIMARY KEY, setda_id TEXT, chapter TEXT, item TEXT, description TEXT, recommendation TEXT, severity TEXT DEFAULT 'minor', status TEXT DEFAULT 'terbuka', created_at TEXT DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_rp_sf_setda ON renja_perubahan_setda_findings(setda_id);
